steps.script:
var ov = tree.root.get_node("/root/TutorialOverlay")
var fd = tree.root.get_node("/root/Main/FormationsDialog")
var gap = float(fd.position.x) - ov.card_rect().end.x
print("[T2CARD] card=", ov.card_rect(), " dialog_x=", fd.position.x, " gap=", gap)
return gap

var ov = tree.root.get_node("/root/TutorialOverlay")
var t = str(ov.current_body_text())
return t.contains("LEADER") and t.contains("now he fights wiv his mob")

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is OptionButton and nd.item_count > 0 and nd.get_item_text(0) == "(Unattached)":
		nd.select(1)
		nd.item_selected.emit(1)
		return true
	for c in nd.get_children():
		q.append(c)
return false

var ov = tree.root.get_node("/root/TutorialOverlay")
var fd = tree.root.get_node("/root/Main/FormationsDialog")
return float(fd.position.x) - ov.card_rect().end.x

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is CheckBox and str(nd.text).begins_with("Boyz") and not ("Reserves" in str(nd.text)):
		nd.button_pressed = true
		return true
	for c in nd.get_children():
		q.append(c)
return false

var ov = tree.root.get_node("/root/TutorialOverlay")
var rd = tree.root.get_node_or_null("/root/Main/RollOffDialog")
if rd == null or not rd.visible:
	return 999.0
print("[T2CARD] rolloff card=", ov.card_rect(), " dialog_x=", rd.position.x)
return float(rd.position.x) - ov.card_rect().end.x

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
var q = [tree.root]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is Button and nd.is_visible_in_tree() and "Re-roll" in str(nd.text):
		nd.pressed.emit()
		return true
	for c in nd.get_children():
		q.append(c)
return true

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/ContinueButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var ov = tree.root.get_node("/root/TutorialOverlay")
var c = ov.get_node("InstructorCard")
print("[T2CARD] no-dialog card=", ov.card_rect(), " mode=", ov.get("_card_mode"), " anchors=", c.anchor_left, "/", c.anchor_right, " offsets=", c.offset_left, "/", c.offset_right, " minsize=", c.get_combined_minimum_size())
return ov.card_rect().size.x
